             F (Z_to_bv 64 qdorec_entry) fc None m' (seg_rom asegs)
    /\ munch W m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ qcache_rep m' QG r /\ qcache_rep m' TMP Xd /\ q_lock m' 0 0.

